package ama.storage;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class Task11Fix02LeaseMetadataTraceTest {
 static final String SQL="SELECT id,task_type,pool,state,attempt,lease_owner,expires_at FROM durable_task WHERE (subject_kind='MEETING' AND subject_id=?) ORDER BY id LIMIT 3 FOR UPDATE";
 Map<String,Object> row(String id,String expiry){return new TreeMap<>(Map.of("id",id,"state","RUNNING","attempt","3","lease_owner","owner","expires_at",expiry,"producer_key","unchanged"));}
 Task11Fix02LeaseMetadataTrace fixture(String newExpiry,String field,String value,boolean other,int affected){var t=new Task11Fix02TransferTrace();t.rows.add(Map.of("phase","case","sql",SQL));var x=new Task11Fix02LeaseMetadataTrace(t);x.calls.set(1L);x.sequence.set(5);long thread=Thread.currentThread().threadId();x.statements.add(new Task11Fix02LeaseMetadataTrace.Statement(1,1,thread,"case",SQL));x.statements.add(new Task11Fix02LeaseMetadataTrace.Statement(4,1,thread,"case",SQL));var old=row("a","2030-01-01 00:00:00.000001");var next=row("a",newExpiry);var oldOther=row("b","2030-01-01 00:00:00.000001");var nextOther=new TreeMap<>(oldOther);if(field!=null)(other?nextOther:next).put(field,value);x.reads.add(new Task11Fix02LeaseMetadataTrace.Read(1,2,1,thread,"case",SQL,List.of(old,oldOther)));x.reads.add(new Task11Fix02LeaseMetadataTrace.Read(4,5,1,thread,"case",SQL,List.of(next,nextOther)));if(affected>=0)x.renewals.add(new Task11Fix02LeaseMetadataTrace.Renewal(3,affected));return x;}
 @Test void onlySuccessfulRenewedCurrentExpiryCanRediscover(){var x=fixture("2030-01-01 00:00:20.000001",null,null,false,1);assertNotNull(x.onlyCurrentExpiry(0,"case","a",3,"owner"));}
 @Test void decreasedEqualOrUnsuccessfulExpiryNeverRetries(){for(String expiry:List.of("2029-01-01 00:00:00.000001","2030-01-01 00:00:00.000001"))assertNull(fixture(expiry,null,null,false,1).onlyCurrentExpiry(0,"case","a",3,"owner"));for(int affected:List.of(-1,0,2))assertNull(fixture("2030-01-01 00:00:20.000001",null,null,false,affected).onlyCurrentExpiry(0,"case","a",3,"owner"));}
 @Test void anyOtherMetadataDifferenceNeverRetries(){for(boolean other:List.of(false,true))for(String field:List.of("producer_key","lease_owner","attempt","state"))assertNull(fixture("2030-01-01 00:00:20.000001",field,"changed",other,1).onlyCurrentExpiry(0,"case","a",3,"owner"));assertNull(fixture("2030-01-01 00:00:20.000001","expires_at","2030-01-01 00:00:30.000001",true,1).onlyCurrentExpiry(0,"case","a",3,"owner"));}
 @Test void differentFailureSiteOrRenewalOrderingNeverRetries(){var x=fixture("2030-01-01 00:00:20.000001",null,null,false,1);x.sequence.set(6);x.statements.add(new Task11Fix02LeaseMetadataTrace.Statement(6,1,Thread.currentThread().threadId(),"case","SELECT something_else"));assertNull(x.onlyCurrentExpiry(0,"case","a",3,"owner"));x=fixture("2030-01-01 00:00:20.000001",null,null,false,-1);x.renewals.add(new Task11Fix02LeaseMetadataTrace.Renewal(6,1));assertNull(x.onlyCurrentExpiry(0,"case","a",3,"owner"));}
 @Test void otherCallThreadAndWindowCannotSupplySnapshots(){for(boolean otherCall:List.of(false,true)){var x=fixture("2030-01-01 00:00:20.000001",null,null,false,1);var r=x.reads.getLast();x.reads.set(x.reads.size()-1,new Task11Fix02LeaseMetadataTrace.Read(r.start(),r.end(),otherCall?2:r.callId(),otherCall?r.thread():r.thread()+1,r.phase(),r.sql(),r.rows()));assertNull(x.onlyCurrentExpiry(0,"case","a",3,"owner"));assertEquals("INSUFFICIENT_SAME_CALL_THREAD_READS",x.rejection.get());}var x=fixture("2030-01-01 00:00:20.000001",null,null,false,1);assertNull(x.onlyCurrentExpiry(4,"case","a",3,"owner"));x.calls.set(2L);assertNull(x.onlyCurrentExpiry(0,"case","a",3,"owner"));}
 @Test void renewalCompletedWhileLockedReadWaitsIsObserved(){var x=fixture("2030-01-01 00:00:20.000001",null,null,false,-1);var r=x.reads.getLast();x.reads.set(x.reads.size()-1,new Task11Fix02LeaseMetadataTrace.Read(r.start(),7,r.callId(),r.thread(),r.phase(),r.sql(),r.rows()));x.sequence.set(7);x.renewals.add(new Task11Fix02LeaseMetadataTrace.Renewal(6,1));assertNotNull(x.onlyCurrentExpiry(0,"case","a",3,"owner"));x.renewals.clear();x.renewals.add(new Task11Fix02LeaseMetadataTrace.Renewal(8,1));assertNull(x.onlyCurrentExpiry(0,"case","a",3,"owner"));}
}
